import Foundation

/// One generated file: a repository-relative path and its full contents.
public struct GeneratedFile: Equatable, Sendable {
    public let path: String
    public let contents: String

    public init(path: String, contents: String) {
        self.path = path
        self.contents = contents
    }
}

/// Writes the token model as Swift, in three files:
///
/// - `QeetrixFoundationTokens.swift` — the public, typed token API: the `QeetrixColor` and
///   `QeetrixElevation` cases, and every theme-invariant value (spacing, corners, strokes, focus,
///   opacity, icon metrics, density, motion, typography, font faces).
/// - `Qeetrix<Theme>Tokens.swift` — one internal table per upstream theme with that theme's colour
///   and elevation values. Foundations pick the table from the SwiftUI environment.
///
/// Every declaration carries its upstream token path and CSS variable, so a reader can always find
/// the web definition it came from.
public struct TokenEmitter {
    let model: TokenModel
    let provenance: Provenance
    let fonts: [FontSpec]

    public static let directory = "Sources/Qeetrix/Tokens/Generated"

    public init(model: TokenModel, provenance: Provenance, fonts: [FontSpec]) {
        self.model = model
        self.provenance = provenance
        self.fonts = fonts
    }

    var header: String {
        """
        // GENERATED by qeetrix-gen from \(provenance.qeetrixUIPackage) \(provenance.qeetrixUIVersion) — do not edit.
        // Change the upstream tokens, bump Scripts/Upstream/pins.json, run Scripts/sync-upstream.sh, then Scripts/generate.sh.


        """
    }

    public func files() throws -> [GeneratedFile] {
        guard model.themes == ["light", "dark"] else {
            throw GeneratorError("Qeetrix iOS maps the light and dark themes; upstream registers \(model.themes).")
        }
        return [try foundation()] + (try model.themes.map(themeFile))
    }

    static func themeTypeName(_ theme: String) -> String {
        "Qeetrix" + theme.prefix(1).uppercased() + theme.dropFirst() + "Tokens"
    }

    // MARK: Helpers

    func single(_ token: ResolvedToken) throws -> TokenValue {
        guard token.isThemeInvariant, let value = token.values[model.themes[0]] else {
            throw GeneratorError("\(token.dotted): varies by theme, but iOS reads it as a fixed value.")
        }
        return value
    }

    func dimension(_ token: ResolvedToken) throws -> Double {
        guard case let .dimension(value) = try single(token) else {
            throw GeneratorError("\(token.dotted): expected a dimension.")
        }
        return value
    }

    func number(_ token: ResolvedToken) throws -> Double {
        guard case let .number(value) = try single(token) else {
            throw GeneratorError("\(token.dotted): expected a number.")
        }
        return value
    }

    func doc(_ token: ResolvedToken, _ extra: String? = nil, indent: String = "    ") -> String {
        let source = token.consumable ? "`\(token.dotted)` · `\(token.cssName)`" : "`\(token.dotted)` (primitive scale)"
        guard let extra else { return "\(indent)/// \(source)\n" }
        return "\(indent)/// \(source)\n\(indent)///\n\(indent)/// \(extra)\n"
    }

    func names(_ tokens: [ResolvedToken], dropping prefix: Int, scope: String) throws -> [String] {
        let names = try tokens.map { try SwiftNames.identifier(Array($0.path.dropFirst(prefix)), context: $0.dotted) }
        try SwiftNames.requireUnique(Array(zip(names, tokens.map(\.dotted))), scope: scope)
        return names
    }

    /// Members for a flat group of tokens, separated by blank lines.
    func members(
        _ tokens: [ResolvedToken], dropping prefix: Int, scope: String,
        _ declaration: (String, ResolvedToken) throws -> String
    ) throws -> String {
        let identifiers = try names(tokens, dropping: prefix, scope: scope)
        return try zip(identifiers, tokens).map { try declaration(SwiftNames.declaration($0), $1) }.joined(separator: "\n")
    }

    func cgFloats(_ prefix: [String], scope: String) throws -> String {
        try members(model.tokens(under: prefix), dropping: prefix.count, scope: scope) { name, token in
            let value = try dimension(token)
            return doc(token, "\(swiftNumber(value)) pt") + "    public static let \(name): CGFloat = \(swiftNumber(value))\n"
        }
    }

    func rgba(_ color: ColorMath.EncodedColor) -> String {
        "QeetrixRGBA(.\(color.space.rawValue), \(swiftNumber(color.red)), \(swiftNumber(color.green)), \(swiftNumber(color.blue)), \(swiftNumber(color.alpha)))"
    }

    func describe(_ color: ColorMath.EncodedColor) -> String {
        var text = color.hex
        if color.space == .displayP3 { text += " (Display P3\(color.gamutMapped ? ", gamut-mapped" : ""))" }
        return text
    }

    // MARK: Foundation file

    func foundation() throws -> GeneratedFile {
        let sections = [
            try colorCases(),
            try elevationCases(),
            try dimensions(),
            try motion(),
            try typography(),
            try fontFamilies(),
        ]
        return GeneratedFile(
            path: "\(Self.directory)/QeetrixFoundationTokens.swift",
            contents: header + "import CoreGraphics\nimport Foundation\n\n" + sections.joined(separator: "\n"))
    }

    func colorCases() throws -> String {
        let tokens = model.tokens(under: ["color"])
        let body = try members(tokens, dropping: 1, scope: "QeetrixColor") { name, token in
            guard case let .color(light) = token.values["light"], case let .color(dark) = token.values["dark"] else {
                throw GeneratorError("\(token.dotted): expected a colour in both themes.")
            }
            return doc(token, "Light \(describe(light)) · Dark \(describe(dark))") + "    case \(name) = \(swiftString(token.dotted))\n"
        }
        return """
            /// The semantic colours: every `color.*` token in qeetrix-ui's consumable layer. Raw values are the
            /// upstream token paths. A colour resolves to its light or dark value from the SwiftUI environment;
            /// palette primitives are deliberately not available.
            public enum QeetrixColor: String, CaseIterable, Sendable {
            \(body)}

            """
    }

    func elevationCases() throws -> String {
        let body = try members(model.tokens(under: ["elevation"]), dropping: 1, scope: "QeetrixElevation") { name, token in
            doc(token) + "    case \(name) = \(swiftString(token.dotted))\n"
        }
        return """
            /// The elevation levels (`elevation.*`): layered shadows whose values differ per theme.
            public enum QeetrixElevation: String, CaseIterable, Sendable {
            \(body)}

            """
    }

    func dimensions() throws -> String {
        let opacity = try members(model.tokens(under: ["state", "opacity"]), dropping: 2, scope: "QeetrixOpacity") { name, token in
            doc(token) + "    public static let \(name): Double = \(swiftNumber(try number(token)))\n"
        }
        let iconSizes = try members(model.tokens(under: ["icon", "size"]), dropping: 2, scope: "QeetrixIconSize") { name, token in
            let value = try dimension(token)
            return doc(token, "\(swiftNumber(value)) pt") + "    public static let \(name) = QeetrixIconSize(\(swiftNumber(value)))\n"
        }
        let iconStrokes = try members(model.tokens(under: ["icon", "stroke"]), dropping: 2, scope: "QeetrixIconStroke") { name, token in
            let value = try number(token)
            return doc(token, "\(swiftNumber(value)) units of the 24-unit icon grid")
                + "    public static let \(name) = QeetrixIconStroke(\(swiftNumber(value)))\n"
        }

        // density.<metric>.<mode> → one case per mode, one property per metric.
        let densityTokens = model.tokens(under: ["density"])
        var modes: [String] = []
        var metrics: [String] = []
        for token in densityTokens {
            if !metrics.contains(token.path[1]) { metrics.append(token.path[1]) }
            if !modes.contains(token.path[2]) { modes.append(token.path[2]) }
        }
        var density = try modes.map { "    case \(SwiftNames.declaration(try SwiftNames.identifier([$0], context: "density mode")))\n" }
            .joined()
        for metric in metrics {
            let property = try SwiftNames.identifier([metric], context: "density.\(metric)")
            density +=
                "\n    /// `density.\(metric).*` · `--qx-density-\(metric)-*`, in points.\n    public var \(property): CGFloat {\n        switch self {\n"
            for mode in modes {
                guard let token = densityTokens.first(where: { $0.path == ["density", metric, mode] }) else {
                    throw GeneratorError("density.\(metric).\(mode): missing — every density metric needs every mode.")
                }
                density +=
                    "        case .\(try SwiftNames.identifier([mode], context: token.dotted)): \(swiftNumber(try dimension(token)))\n"
            }
            density += "        }\n    }\n"
        }

        return """
            /// The spacing scale (`space.*`), in points.
            public enum QeetrixSpacing {
            \(try cgFloats(["space"], scope: "QeetrixSpacing"))}

            /// Corner radii (`corner.*`), in points. `corner.circle` (50%) is a shape rather than a length:
            /// use `Circle` or `Capsule`.
            public enum QeetrixCorner {
            \(try cgFloats(["corner"], scope: "QeetrixCorner"))}

            /// Stroke widths (`stroke.width.*`), in points.
            public enum QeetrixStroke {
            \(try cgFloats(["stroke", "width"], scope: "QeetrixStroke"))}

            /// Focus indicator geometry (`focus.*`), in points. The ring colour is `QeetrixColor.focusRing`.
            public enum QeetrixFocus {
            \(try cgFloats(["focus"], scope: "QeetrixFocus"))}

            /// State opacities (`state.opacity.*`).
            public enum QeetrixOpacity {
            \(opacity)}

            extension QeetrixIconSize {
            \(iconSizes)}

            extension QeetrixIconStroke {
            \(iconStrokes)}

            /// Control and row metrics per density (`density.*`). On the web, the `control.*` tokens resolve to
            /// the active density's values; here a view reads them from its density.
            public enum QeetrixDensity: String, CaseIterable, Sendable {
            \(density)}

            """
    }

    func motion() throws -> String {
        var durations: [String] = []
        var easings: [String] = []
        var reduced: [String] = []
        for token in model.tokens(under: ["motion"]) {
            let value = try single(token)
            switch (token.path[1], value) {
            case let ("duration", .duration(seconds)):
                let name = SwiftNames.declaration(try SwiftNames.identifier([token.path[2]], context: token.dotted))
                durations.append(
                    doc(token, "\(swiftNumber(seconds * 1000)) ms")
                        + "    public static let \(name) = QeetrixDuration(seconds: \(swiftNumber(seconds)))\n")
            case let ("easing", .easing(points)):
                let name = SwiftNames.declaration(try SwiftNames.identifier([token.path[2]], context: token.dotted))
                easings.append(
                    doc(token) + "    public static let \(name) = QeetrixEasing(\(points.map(swiftNumber).joined(separator: ", ")))\n")
            case let ("reduced", .duration(seconds)) where token.path[2] == "duration":
                reduced.append(
                    doc(token, "\(swiftNumber(seconds * 1000)) ms, used instead of any duration when Reduce Motion is on.")
                        + "    public static let reducedDuration = QeetrixDuration(seconds: \(swiftNumber(seconds)))\n")
            case let ("reduced", .easing(points)) where token.path[2] == "easing":
                reduced.append(
                    doc(token, "Used instead of any easing when Reduce Motion is on.")
                        + "    public static let reducedEasing = QeetrixEasing(\(points.map(swiftNumber).joined(separator: ", ")))\n")
            default:
                throw GeneratorError("\(token.dotted): no Swift mapping for this motion token.")
            }
        }
        return """
            extension QeetrixDuration {
            \(durations.joined(separator: "\n"))}

            extension QeetrixEasing {
            \(easings.joined(separator: "\n"))}

            extension QeetrixMotion {
            \(reduced.joined(separator: "\n"))}

            """
    }

    func typography() throws -> String {
        var weights: [(name: String, value: Double)] = []
        let weightBody = try members(model.tokens(under: ["font", "weight"]), dropping: 2, scope: "QeetrixFontWeight") { name, token in
            let value = try number(token)
            weights.append((name, value))
            return doc(token) + "    public static let \(name) = QeetrixFontWeight(\(swiftNumber(value)))\n"
        }
        var geometries: [(name: String, value: Double)] = []
        let geometryBody = try members(model.tokens(under: ["font", "geometry"]), dropping: 2, scope: "QeetrixFontGeometry") {
            name, token in
            let value = try number(token)
            geometries.append((name, value))
            return doc(token) + "    public static let \(name) = QeetrixFontGeometry(\(swiftNumber(value)))\n"
        }

        let families = Dictionary(uniqueKeysWithValues: fonts.map { ($0.webFamily, $0.family) })
        let roleTokens = model.tokens(under: ["typography"])
        var roles: [String] = []
        for token in roleTokens where !roles.contains(token.path[1]) { roles.append(token.path[1]) }

        var cases: [String] = []
        var specs: [String] = []
        var roleNames: [(name: String, source: String)] = []
        for role in roles {
            let name = try SwiftNames.identifier([role], context: "typography.\(role)")
            roleNames.append((name, "typography.\(role)"))
            func field(_ key: String) -> ResolvedToken? {
                roleTokens.first { $0.path == ["typography", role, key] }
            }
            guard let familyToken = field("font-family"), let sizeToken = field("font-size"),
                let weightToken = field("font-weight"), let lineHeightToken = field("line-height"),
                let spacingToken = field("letter-spacing")
            else {
                throw GeneratorError("typography.\(role): missing one of font-family, font-size, font-weight, line-height, letter-spacing.")
            }
            guard case let .fontFamily(webFamily) = try single(familyToken), let family = families[webFamily] else {
                throw GeneratorError(
                    "typography.\(role).font-family: no bundled font for this family (bundled: \(families.keys.sorted())).")
            }
            let weight = try number(weightToken)
            guard let weightName = weights.first(where: { $0.value == weight })?.name else {
                throw GeneratorError("typography.\(role).font-weight: \(weight) is not on the font.weight scale.")
            }
            guard case let .em(letterSpacing) = try single(spacingToken) else {
                throw GeneratorError("typography.\(role).letter-spacing: expected em.")
            }
            var geometry = "nil"
            if let geometryToken = field("font-geometry") {
                let value = try number(geometryToken)
                guard let geometryName = geometries.first(where: { $0.value == value })?.name else {
                    throw GeneratorError("typography.\(role).font-geometry: \(value) is not on the font.geometry scale.")
                }
                geometry = ".\(geometryName)"
            }
            let size = try dimension(sizeToken)
            let lineHeight = try number(lineHeightToken)
            cases.append(
                "    /// `typography.\(role).*` · `--qx-typography-\(role)-*`\n    ///\n    /// \(webFamily), \(swiftNumber(size)) pt, weight \(swiftNumber(weight)), line height \(swiftNumber(lineHeight))×.\n"
                    + "    case \(SwiftNames.declaration(name))\(name == role ? "" : " = \(swiftString(role))")\n")
            specs.append(
                "        case .\(name):\n            QeetrixTextRoleTokens(\n                family: .\(family), size: \(swiftNumber(size)), weight: .\(weightName),\n                lineHeight: \(swiftNumber(lineHeight)), letterSpacing: \(swiftNumber(letterSpacing)), geometry: \(geometry))\n"
            )
        }
        try SwiftNames.requireUnique(roleNames, scope: "QeetrixTextRole")

        return """
            extension QeetrixFontWeight {
            \(weightBody)
                /// The weight scale, lightest first.
                public static let scale: [QeetrixFontWeight] = [\(weights.map { ".\($0.name)" }.joined(separator: ", "))]
            }

            /// Positions on Qeet Sans's GEOM axis — the letter style, from accessibility-first neutral forms
            /// to fully geometric ones.
            extension QeetrixFontGeometry {
            \(geometryBody)}

            /// The Qeetrix typography roles (`typography.*`). Raw values are the upstream role names.
            public enum QeetrixTextRole: String, CaseIterable, Sendable {
            \(cases.joined(separator: "\n"))
                /// The role's token values.
                public var tokens: QeetrixTextRoleTokens {
                    switch self {
            \(specs.joined())        }
                }
            }

            """
    }

    func fontFamilies() throws -> String {
        var cases: [String] = []
        var faces: [String] = []
        for font in fonts {
            cases.append(
                "    /// \(font.webFamily) on the web: \(font.info.familyName), \(font.info.version) (\(font.repository) \(font.tag)).\n    case \(SwiftNames.declaration(font.family))\n"
            )
            let axes = font.info.axes.map {
                "QeetrixFontAxis(tag: \(swiftString($0.tag)), minimum: \(swiftNumber($0.minimum)), defaultValue: \(swiftNumber($0.defaultValue)), maximum: \(swiftNumber($0.maximum)))"
            }
            faces.append(
                """
                        case .\(font.family):
                            QeetrixFontFace(
                                resourceName: \(swiftString(font.resourceName)),
                                postScriptName: \(swiftString(font.info.postScriptName)),
                                familyName: \(swiftString(font.info.familyName)),
                                webFamily: \(swiftString(font.webFamily)),
                                axes: [
                                    \(axes.joined(separator: ",\n                    "))
                                ])

                """)
        }
        return """
            /// The bundled typefaces. Each is the native TTF of the exact font the web ships as WOFF2.
            public enum QeetrixFontFamily: String, CaseIterable, Sendable {
            \(cases.joined(separator: "\n"))
                /// The bundled font file and its variation axes, as read from the font at generation time.
                public var face: QeetrixFontFace {
                    switch self {
            \(faces.joined())        }
                }
            }

            """
    }

    // MARK: Theme files

    func themeFile(_ theme: String) throws -> GeneratedFile {
        let colors = model.tokens(under: ["color"])
        let colorNames = try names(colors, dropping: 1, scope: "QeetrixColor")
        var colorCases = ""
        for (name, token) in zip(colorNames, colors) {
            guard case let .color(value) = token.values[theme] else {
                throw GeneratorError("\(token.dotted) (\(theme)): expected a colour.")
            }
            colorCases += "        case .\(name): \(rgba(value))\n"
        }

        let elevations = model.tokens(under: ["elevation"])
        let elevationNames = try names(elevations, dropping: 1, scope: "QeetrixElevation")
        var elevationCases = ""
        for (name, token) in zip(elevationNames, elevations) {
            guard case let .shadow(layers) = token.values[theme] else {
                throw GeneratorError("\(token.dotted) (\(theme)): expected a shadow list.")
            }
            if layers.isEmpty {
                elevationCases += "        case .\(name): []\n"
                continue
            }
            elevationCases += "        case .\(name):\n            [\n"
            for layer in layers {
                elevationCases +=
                    "                QeetrixShadowLayer(x: \(swiftNumber(layer.x)), y: \(swiftNumber(layer.y)), blur: \(swiftNumber(layer.blur)), spread: \(swiftNumber(layer.spread)), isInset: \(layer.inset), rgba: \(rgba(layer.color))),\n"
            }
            elevationCases += "            ]\n"
        }

        let typeName = Self.themeTypeName(theme)
        return GeneratedFile(
            path: "\(Self.directory)/\(typeName).swift",
            contents: header + """
                /// The `\(theme)` theme's colour and elevation values (`tokens.json` → `\(theme)`). Internal: views
                /// read them through `QeetrixColor` and `QeetrixElevation`, which choose the theme from the
                /// SwiftUI environment.
                enum \(typeName) {
                    static func color(_ color: QeetrixColor) -> QeetrixRGBA {
                        switch color {
                \(colorCases)        }
                    }

                    static func elevation(_ elevation: QeetrixElevation) -> [QeetrixShadowLayer] {
                        switch elevation {
                \(elevationCases)        }
                    }
                }

                """)
    }
}
